ORTH=[['希腊 orthos 直的、正确的 → ortho-','物理上直，或符合某种规范']]
ODONT=ORTH+[['近代 ortho- + 希腊 odont- 牙 + -ia → orthodontia','用古典成分命名牙齿、颌部位置矫治的学科']]
CORD=[['希腊 khorde 肠线、琴弦 → 拉丁 chorda','由动物肠制成的弦 → 线、弦'],['古法语 corde → 中古英语 corde → cord','绳索；后来也说电线和细长束状结构']]
W += [
E('orthodontist','英 /ˌɔːθəˈdɒntɪst/；美 /ˌɔːrθəˈdɑːntɪst/','正畸医生；牙齿矫正专科医生','专门关注牙齿和上下颌位置、咬合配合的牙科医生。','orthodontia 相关词干 + -ist 从业者；ortho- 直、正确，odont- 牙，指出工作的对象和目标；不经较晚记录的英语 orthodontic 才形成。',ODONT+[['英语 orthodontia 词干 + -ist → orthodontist','从事牙齿、颌部位置矫治的人']],'see an orthodontist 是去看正畸医生；an orthodontist’s assessment 是正畸评估。它是牙科的专科名称，不是所有牙科医生的同义词。','see an orthodontist；an orthodontist’s assessment；refer someone to an orthodontist。','dentist 是牙科医生的广义名称；orthodontist 特别指正畸专科，不能从词根直就推断每个人都需要把牙变直。',('The dentist referred her to an orthodontist.','牙医把她转诊给正畸医生。'),('The orthodontist explained the proposed treatment plan.','正畸医生解释了拟定的治疗方案。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/orthodontist','https://www.etymonline.com/word/orthodontist']),
E('orthodontic','英 /ˌɔːθəˈdɒntɪk/；美 /ˌɔːrθəˈdɑːntɪk/','正畸的；牙齿矫正的','说明一种检查、治疗或装置与调整牙齿、颌部位置有关。','由 orthodontia 的词干形成 -ic 形容词；现代可看到 ortho- + odont- + -ic，别把它拆成 orth + 英语 dont。',ODONT+[['英语 orthodontia 词干 + -ic → orthodontic','正畸学科 → 正畸相关的']],'orthodontic treatment 是正畸治疗；orthodontic appliances 是正畸装置。词只描述用途，不说明具体应该采用哪一种方法。','orthodontic treatment；an orthodontic assessment；orthodontic appliances。','dental 范围是牙科整体；orthodontic 更窄，主要关心排列、位置和咬合。',('The clinic provides orthodontic assessments for adults and children.','这家诊所为成人和儿童提供正畸评估。'),('The leaflet explains the purpose of each orthodontic appliance.','说明册解释了每种正畸装置的用途。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/orthodontic','https://www.etymonline.com/word/orthodontia']),
E('orthodontics','英 /ˌɔːθəˈdɒntɪks/；美 /ˌɔːrθəˈdɑːntɪks/','正畸学；牙齿矫正治疗','把牙齿、颌部位置和咬合的矫治当作一门专业或一类治疗。','orthodontic + 学科后缀 -s，形式上也可分析 ortho- + odont- + -ics；它是学科名，不是几个正畸医生的复数。',ODONT+[['英语 orthodontic → orthodontics','正畸相关 → 正畸这门学科和治疗领域']],'specialize in orthodontics 是专攻正畸；Orthodontics is... 按学科通常接单数动词。名字里虽有 straight，也不只关心笑起来整不整齐。','specialize in orthodontics；a course in orthodontics；the field of orthodontics。','orthodontist 是人，orthodontics 是专业领域；orthopedic 则与骨科相关，不能因 ortho- 相同就混为牙科。',('She plans to specialize in orthodontics after dental school.','牙科学校毕业后，她计划专攻正畸。'),('Orthodontics concerns the alignment of teeth and jaws.','正畸学关注牙齿和颌部的位置关系。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/orthodontics','https://en.wiktionary.org/wiki/orthodontics#English']),
E('orthographic','英 /ˌɔːθəˈɡræfɪk/；美 /ˌɔːrθəˈɡræfɪk/','拼写的；正字法的；正投影的','写字时按某套规则呈现词形；绘图时则按正投影呈现物体，两个技术语境要分开。','绘图义接 ortho- 正 + graphic 绘图；拼写义与较早 orthography 正字法 + -ic 相连，不用单一路线覆盖所有意思。',ORTH+[['并列构词：ortho- + graphic；orthography + -ic','正投影绘图；规范书写与拼写'],['英语 orthographic 的两种常见专业用途','语言中的拼写系统；制图中的正投影']],'orthographic conventions 是拼写惯例；orthographic projection 是正投影，不按透视近大远小缩放。看到句子先判断它在谈语言还是工程图。','orthographic conventions；orthographic differences；orthographic projection。','phonetic 关注声音，orthographic 关注书写形式；perspective drawing 有透视效果，orthographic projection 按垂直投射关系表示。',('The two editions differ mainly in orthographic conventions.','这两个版本主要在拼写惯例上不同。'),('The engineer prepared an orthographic projection of the part.','工程师绘制了这个零件的正投影图。'),sources=['https://www.etymonline.com/word/orthographic','https://www.oxfordlearnersdictionaries.com/definition/english/orthographic']),
E('orthotic','英 /ɔːˈθɒtɪk/；美 /ɔːrˈθɑːtɪk/','矫形的；矫形器；矫形鞋垫','从外部给身体某个部位支撑或调整作用的装置，日常很常指鞋内的支撑垫。','ortho- 直、矫正 + -otic；属于 orthosis、orthotics 这一近代矫形词族，不能拆成与耳朵 otic 有关。',ORTH+[['近代 ortho- + -otic → orthotic','与外部支撑、矫形相关；也作装置名词']],'orthotic devices 是矫形装置；shoe orthotics 常指鞋内支撑垫。形容词范围比鞋垫广，涉及不同部位的支具。','an orthotic device；orthotic support；shoe orthotics；a custom orthotic。','prosthetic 常指替代缺失部位的假体相关；orthotic 主要帮助已有部位支撑、对位或功能，不能一概当作假肢。',('The report describes a new orthotic device for ankle support.','报告介绍了一种用于支撑脚踝的新矫形装置。'),('He placed the orthotic inside his shoe.','他把矫形鞋垫放进鞋里。'),sources=['https://www.collinsdictionary.com/dictionary/english/orthotic','https://en.wiktionary.org/wiki/orthotic#English']),
E('orthogonal','英 /ɔːˈθɒɡənəl/；美 /ɔːrˈθɑːɡənəl/','正交的；垂直的；相互独立的〔比喻〕','像横轴和纵轴成直角，分别指向不同方向；工作讨论中也借来表示两件事互不直接牵涉。','希腊 orthogonios 直角的，经晚期拉丁 orthogonius、法语 orthogone/orthogonal 传入；ortho- 正、直 + gonia 角。',ORTH+[['希腊 ortho- + gonia → orthogonios → 晚期拉丁 orthogonius → 法语 orthogonal → 英语 orthogonal','成直角的 → 正交；后用于抽象独立关系']],'orthogonal axes 是相互垂直的坐标轴；That question is orthogonal to this one 表示问题属于另一个维度，不是相反立场。数学中更广的正交关系由相应内积定义。','orthogonal axes；orthogonal vectors；orthogonal to；orthogonal concerns。','opposite 是相反；orthogonal 的普通比喻是相互独立或无直接关系。统计中的正交也不能在所有条件下自动等同概率独立。',('The diagram uses three mutually orthogonal axes.','图中使用了三条两两垂直的坐标轴。'),('The licensing question is orthogonal to the choice of file format.','许可问题与选择哪种文件格式是两回事。'),sources=['https://www.etymonline.com/word/orthogonal','https://www.collinsdictionary.com/dictionary/english/orthogonal']),
E('cord','英 /kɔːd/；美 /kɔːrd/','细绳；电线；索状或束状结构','抓住细长、能连起来或绑起来的形状：绳子、电线和某些身体结构都能这样称呼。','希腊 khorde 肠线、琴弦，经拉丁 chorda、古法语 corde 进入英语，旧有乐器弦义也在这条线上。',CORD,'a power cord 是电源线；a length of cord 是一段细绳；spinal cord 是脊髓，vocal cords 是声带。身体用法借形状命名，不意味着里面是一根普通绳。','a power cord；an extension cord；tie with cord；vocal cords。','cord 常比 rope 细，具体边界依用途而变。声带通常写 vocal cords；音乐和弦写 chord。',('She tied the parcel with a piece of cord.','她用一段细绳绑好了包裹。'),('The power cord does not reach the socket.','电源线够不到插座。'),sources=['https://www.etymonline.com/word/cord','https://www.oxfordlearnersdictionaries.com/definition/english/cord']),
E('cordless','英 /ˈkɔːdləs/；美 /ˈkɔːrdləs/','无线的；不需拖着电线使用的','使用时不用被一条线拴在插座或底座旁，可以更自由地移动。','cord + -less 无；在电器语境中 cord 指电源线或连接线。',CORD+[['英语 cord + -less → cordless','没有线缆牵连的']],'a cordless drill 是充电式无线电钻；a cordless phone 是无绳电话。cordless 不保证设备永远不用充电线，也不等于所有功能都通过无线网络。','a cordless drill；a cordless vacuum cleaner；a cordless phone。','wireless 强调无线传输或连接；cordless 常强调使用时无需线缆拖着，两词可重叠但侧重点不同。',('The cordless drill is easier to use on the ladder.','在梯子上使用这把无线电钻更方便。'),('She chose a cordless vacuum cleaner for the stairs.','她选了一台无线吸尘器来清扫楼梯。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/cordless','https://en.wiktionary.org/wiki/cordless#English']),
E('corded','英 /ˈkɔːdɪd/；美 /ˈkɔːrdɪd/','带线的；有绳纹的；绷得像索状的','有一条实际的连接线，或表面出现一条条像绳的凸纹。','cord + -ed，可表示带有绳线；由绳状外形又用于布料凸纹和绷起的肌肉。',CORD+[['英语 cord + -ed → corded','带线的；有绳状凸起的']],'a corded phone 是有线电话；corded fabric 是有凸起绳纹的布料。两种用法共享线或绳的形状，不都在谈电。','a corded phone；a corded drill；corded fabric；corded muscles。','cordless 是否定线缆，corded 是带线；corded 布料不必插电，它只描述纹理。',('The workshop keeps a corded drill for longer jobs.','车间留着一把有线电钻，用于耗时较长的工作。'),('The cushion was covered in a soft, corded fabric.','靠垫外面包着柔软的绳纹布料。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/corded','https://en.wiktionary.org/wiki/corded#English']),
E('corduroy','英 /ˈkɔːdərɔɪ/；美 /ˈkɔːrdərɔɪ/','灯芯绒；条绒','布面有一道道平行凸条，摸起来像一排细绳，常用来做裤子或夹克。','词源不完全确定，通常认为 cord 绳纹 + 旧织物名 duroy；法国国王的布那类说法缺少可靠法语记录。',[['可能的英语 cord 绳纹 + 旧织物名 duroy','常见解释；duroy 的更早来源不清'],['英语 corduroy','有凸起平行绒条的织物；后也作衣物修饰语']],'a corduroy jacket 是灯芯绒夹克；corduroys 可以指灯芯绒裤，口语也常说 cords。粗细不同的凸条会带来不同纹理。','a corduroy jacket；corduroy trousers；soft corduroy；a pair of cords。','velvet 是绒面织物的一大类；corduroy 的显著特点是平行凸条。与 cord 的联系很可能成立，但不应把猜测装成完整定论。',('He wore a brown corduroy jacket to the meeting.','他穿着棕色灯芯绒夹克参加会议。'),('The wide ridges give this corduroy a distinctive texture.','较宽的绒条让这种灯芯绒有了鲜明的质感。'),sources=['https://www.etymonline.com/word/corduroy','https://www.oxfordlearnersdictionaries.com/definition/english/corduroy']),
E('paracord','美 /ˈperəˌkɔːrd/ 或 /ˈpærəˌkɔːrd/','伞绳；轻质编织绳','原本联系降落伞悬挂绳，如今也常见于户外绑扎和编织手工。','这里 para- 取自 parachute 降落伞，接 cord 绳；不能一概当成希腊 para- 旁边。',CORD+[['英语 parachute 的 para- + cord → paracord','降落伞绳 → 常用于户外和编织的轻质绳']],'a paracord bracelet 是伞绳编织手环；a length of paracord 是一段伞绳。今天产品材质、规格不一，名字不自动保证同样承重或都适合降落伞用途。','a paracord bracelet；a length of paracord；braid paracord。','cord 是通称；paracord 强调降落伞绳相关的类型和历史。外观相似并不能据此确认某根绳子的性能。',('She braided the paracord into a bright bracelet.','她把伞绳编成了一条鲜亮的手环。'),('He used a short length of paracord to tie the rolled blanket.','他用一小段伞绳绑住卷好的毯子。'),sources=['https://www.merriam-webster.com/dictionary/paracord','https://en.wiktionary.org/wiki/paracord#English']),
E('chord','英 /kɔːd/；美 /kɔːrd/','和弦；几何中的弦；引起共鸣的心弦','几何里是一条连接曲线上两点的直线段；音乐里是几个音一起组成的和声单位，两种意思历史上发生了拼写合流。','几何弦义是 cord 受拉丁 chorda 影响恢复 h；音乐和弦义主要接 accord 的缩短，受表示弦的 cord/chord 影响。两条来源要并列。',[['弦线：希腊 khorde → 拉丁 chorda → 法语 corde → 英语 cord → chord','像弦的细线、结构；几何中连接曲线上两点的线段'],['并列和声线：法语 / 英语 accord 和谐 → cord → chord','缩短词与弦的拼写相互影响 → 音乐和弦'],['strike a chord 的心弦比喻','把感受比作能被拨动的弦 → 引起共鸣']],'play a chord 是弹一个和弦；a chord of a circle 是圆的一条弦；strike a chord with someone 是引起共鸣。例子不同，不能只套同一个中文弦。','play a chord；a major chord；a chord of a circle；strike a chord with。','cord 是细绳或电线；chord 是和弦或几何弦。discord 不和接拉丁 cor 心的一线，不能凭近形当成希腊弦的直接后代。',('She played a simple chord on the piano.','她在钢琴上弹了一个简单和弦。'),('The story struck a chord with many readers.','这个故事引起了许多读者的共鸣。'),('A diameter is a chord that passes through the centre of a circle.','直径是经过圆心的一条弦。'),sources=['https://www.etymonline.com/word/chord','https://www.oxfordlearnersdictionaries.com/definition/english/chord']),
]
