DEFERRED={'aesthesia':'较冷门感觉能力术语，通用阅读优先 anaesthesia 与 aesthetic。','aesthesis':'罕见感知名词，暂略。','cosmogeny':'较少用宇宙起源词形，优先 cosmogony。','ortholog':'专门基因演化术语，暂略。','orthologous':'专门基因演化术语，暂略。','orthodontia':'较旧的正畸学名称，历史中说明，词条优先 orthodontics。','orthosis':'较专门矫形器术语，通用阅读先掌握 orthotic。','orthonym':'较冷门名称分类术语，暂略。','orthoscope':'较冷门专用器械名称，暂略。','orthostat':'专门考古、建筑石板术语，暂略。','orthostyle':'专门建筑柱列术语，暂略。','discord':'来自拉丁 cor/cordis 心的分歧支线，非希腊 khorde 弦；完整精讲保留在 cor 根。','cordy':'罕用有绳状纹理形容词，优先 corded。','corder':'罕用职业或工具名称，暂略。','cordite':'较专门发射药名称，暂略。','monochord':'专门乐器和音律研究术语，暂略。','tetrachord':'专门乐理术语，暂略。','hexachord':'专门乐理术语，暂略。','polychord':'专门音乐、和声术语，暂略。','chordata':'动物分类名称，暂不列入通用学习词族。'}
def rootwords(i):return [w for w in ASSIGN['roots'][i]['family'] if w not in DEFERRED]
def rootexclude(i):return {w:DEFERRED[w] for w in list(ASSIGN['roots'][i]['family'])+ASSIGN['roots'][i]['unmatched'] if w in DEFERRED}
MICR_ROOT=dict(id='C0736',meaning='小；微小；计量中的百万分之一',core='把观察和行动缩到小尺度：看小东西、做小芯片、分析微小生命；在单位前则有严格的数值意义。',image='希腊 mikros 小 → micro-；micro- + -scope → microscope；近代法语 microbe → microbe、microbial；micro- + cosm- 世界 → microcosm。计量 micro- + metre → 微米。',intro='microphone、microscope、microchip 都与小尺度有关，但不是把任何东西都除以一百万。只有 micro- 用作计量前缀时，才严格表示百万分之一。micrometer 还能指精密测量仪，和长度单位的常见重音不同。',forms='micro- 常读 /ˈmaɪkrəʊ/ 或 /ˈmaɪkroʊ/；后面的词形会改变整体重音。microscope 首重音，microscopic 重音后移。micrometre 是英式单位拼写，micrometer 是美式单位拼写，也表示仪器。',branches=[['看小、听声与观察方式','microscope, microscopic, microscopically, microphone'],['微小生命','microbe, microbial, microorganism, microbiology, microbiologist'],['微小长度','micrometer, micrometre, micron'],['电子设备与波','microchip, microprocessor, microwave'],['环境中的小碎片','microplastic, microplastics'],['小范围的社会与活动','microcosm, microeconomics, microfinance, micromanage, micromanagement']],contrasts='microchip 是芯片统称，microprocessor 是处理器。microcosm 是缩影，不必真的缩小一百万倍。micromanage 常批评连小细节都管，microfinance 则说小额金融服务。',practice='区分 microbe、microbial、microbiology；分别读仪器与单位的 micrometer；用 microcosm 说明一个小场景怎样反映更大整体。',words=rootwords(130),exclude=rootexclude(130))
AESTH_ROOT=dict(id='C0020',meaning='感觉；感知；后来引申为审美',core='人先能感觉，再对感觉到的形式产生审美判断；没有感觉与感觉联结，又分别形成麻醉、联觉的名字。',image='希腊 aisthesis 感觉、aisthetikos 感知相关 → 德语、法语哲学词 → aesthetic；an- 无 + 感觉 → anaesthesia；syn- 一起 + 感觉 → synaesthesia。',intro='aesthetic 是审美，anaesthetic 是麻醉相关，多出来的否定成分把意思带向另一边。美学词汇并非一开始只说漂亮；它从感知问题逐渐转到美和艺术。医学名称则沿感觉缺失的历史发展。',forms='英式常保留 ae，美式一些词常简写 e：anaesthesia/anesthesia、anaesthetic/anesthetic。aesthetic 与 aesthete 的常见首音有 /iː/、/e/ 变体；主重音位置也不一样。',branches=[['美感、风格与研究','aesthetic, aesthetically, aesthetics, aesthete'],['没有感觉与麻醉药物','anaesthesia, anesthesia, anaesthetic, anesthetic'],['实施麻醉的人','anaesthetist, anesthetist'],['感觉之间的联结','synaesthesia, synesthesia']],contrasts='aesthetic 是审美，anesthetic 是麻醉；anaesthesia 是状态，anaesthetic 是药物或修饰词。syn- 一起与 an- 没有指向不同感觉关系。联觉现象也不能仅凭一条感官比喻判断。',practice='把 aesthetic、anaesthetic、anaesthetist 分别用于设计、药物和人；解释为什么局部麻醉不一定让人失去意识；比较联觉与有意使用的文学通感。',words=rootwords(131),exclude=rootexclude(131))
COSM_ROOT=dict(id='C0261',meaning='秩序；世界、宇宙；装饰与美化',core='把东西安排得有秩序，可以想到井然的世界，也可以想到收拾、装饰得好看的外表。',image='希腊 kosmos 秩序、世界、装饰 → cosmos、cosmic；cosmo- + -logy → cosmology；kosmein 装饰 → kosmetikos → cosmetic。',intro='cosmos 与 cosmetic 看似一个宏大、一个日常，却共享秩序和装饰的古老语义背景。cosmology 研究宇宙整体，cosmonaut 是宇航员；cosmopolitan 则把人看作世界公民。每一支的现实用途仍要分别掌握。',forms='cosmos、cosmic 多首重音；cosmology、cosmologist 重音在第二音节，cosmological 再后移。cosmetic 与 cosmic 中间只多几个字母，意思却不同。',branches=[['宇宙整体与尺度','cosmos, cosmic'],['宇宙研究与起源','cosmology, cosmological, cosmologist, cosmogony'],['航行到太空的人','cosmonaut'],['大世界与小世界','cosmopolitan, cosmopolitanism, cosmopolite, microcosm'],['装饰、美化与表面改变','cosmetic, cosmetics, cosmetically']],contrasts='cosmologist 是学者，cosmonaut 是宇航员。cosmic 是宇宙的，cosmetic 常说美容或仅改外观。cosmogony 重起源，cosmology 范围更广。',practice='解释 cosmetic changes 为什么可能是批评；比较 cosmology 与 cosmogony；用 microcosm 和 cosmopolitan 描写同一座城市的两个角度。',words=rootwords(132),exclude=rootexclude(132))
ORTH_ROOT=dict(id='C0922',meaning='直；正确；符合某种规范',core='物体可以摆直，牙齿位置可以矫治，拼写可以按规范；对意见说正统，则是相对于某个群体认可的标准。',image='希腊 orthos 直、正确 → ortho-；+ doxa 意见 → orthodox；+ odont- 牙 → orthodontics；+ graph- 写 → orthography；+ gonia 角 → orthogonal。',intro='ortho- 不只等于好。orthodox 说符合正统或惯例，不保证一种意见已经被证明正确；orthogonal 则是几何正交，不能解释成正统的角度。医学和制图词也有各自具体含义。',forms='orthodontist 是人，orthodontic 是修饰词，orthodontics 是学科。orthographic 与 orthography 相关；orthogonal 中 gon- 是角。orthopaedic/orthopedic 等地区拼写不改变主要含义。',branches=[['意见与惯例','orthodox, orthodoxy, unorthodox'],['牙科位置矫治','orthodontist, orthodontic, orthodontics'],['骨科与外部支撑','orthopedic, orthopaedic, orthopedics, orthopaedics, orthotic'],['书写、制图与几何','orthography, orthographic, orthogonal, orthocenter, orthocentric']],contrasts='orthodox 指相对正统，correct 直接说正确，两者不是逻辑等价。orthodontics 属牙科，orthopedics 属骨科。orthogonal 常说垂直或独立，不等于相反。',practice='区分 orthodontist、orthodontic、orthodontics 的句法角色；解释 orthographic 在语言与工程图中的不同意思；用 orthogonal to 表达两个问题属于不同方面。',words=rootwords(133),exclude=rootexclude(133))
CHORD_ROOT=dict(id='C0213',meaning='弦；绳；细长连接物',core='先是拉紧的一条弦，再扩展到绳索、电线和细长结构；同形的音乐和弦还混合了另一条和谐来源。',image='希腊 khorde → 拉丁 chorda → 古法语 corde → cord → corded、cordless；恢复古典 h 的 chord 有几何弦义。并列 accord 和谐 → 缩短 cord → 受弦词影响写 chord〔和弦〕。',intro='cord、corded、cordless 很适合一起学：有线、无线都围绕一条连接线。corduroy 的凸纹像细绳，但具体词源仍有不确定性。chord 的和弦义与弦的拼写发生合流，不能把合流后的字形当作唯一源头。',forms='cord 与 chord 同音，h 不发音。corded 的 -ed 在 /d/ 后另成 /ɪd/ 一节；cordless 用 -less 表示没有连接线。paracord 的 para- 来自 parachute，不直接套旁边。',branches=[['绳索与电线','cord'],['带线与无线','corded, cordless'],['像细绳的布纹','corduroy'],['户外与编织绳','paracord'],['几何弦、和弦与共鸣','chord']],contrasts='vocal cords 通常写 cord，音乐和弦写 chord。discord 接 cor 心的另一支，已有独立精讲。corduroy 不是已证实的法国国王的布，名字相似的故事不能替代证据。',practice='用 corded 与 cordless 比较两种工具；解释 strike a chord；分别画出 chord 的几何弦来源与音乐和弦来源，用文字箭头即可。',words=rootwords(134),exclude=rootexclude(134))
roots=[MICR_ROOT,AESTH_ROOT,COSM_ROOT,ORTH_ROOT,CHORD_ROOT]
